import json, os, shutil, subprocess, sys, tempfile

BIN = "/workspace/executable"

def run(content, name="Deck.md", extra=None, show_lines=True, binary=False):
    d = tempfile.mkdtemp(prefix="hc_", dir="/tmp/explore/md-parse-basic/runs")
    p = os.path.join(d, name)
    if binary:
        open(p, "wb").write(content)
    else:
        open(p, "w", encoding="utf-8").write(content)
    if extra:
        for fn, c in extra.items():
            fp = os.path.join(d, fn)
            os.makedirs(os.path.dirname(fp), exist_ok=True)
            if isinstance(c, bytes): open(fp,"wb").write(c)
            else: open(fp,"w",encoding="utf-8").write(c)
    r = subprocess.run([BIN, "export", d], capture_output=True, text=True)
    out = {"exit": r.returncode, "stderr": r.stderr, "dir": d}
    if r.returncode == 0:
        try:
            j = json.loads(r.stdout)
            cards = sorted(j["cards"], key=lambda c: (c["location"]["filePath"], c["location"]["lineStart"], json.dumps(c["content"])))
            out["cards"] = [{"line": [c["location"]["lineStart"], c["location"]["lineEnd"]],
                             "file": os.path.basename(c["location"]["filePath"]),
                             "deck": c["deckName"],
                             "hash": c["hash"][:8],
                             "family": (c["familyHash"] or "")[:8],
                             "content": c["content"]} for c in cards]
        except Exception as e:
            out["parse_err"] = str(e); out["stdout"] = r.stdout[:2000]
    else:
        out["stdout"] = r.stdout[:2000]
    return out

def show(label, content, **kw):
    res = run(content, **kw)
    print("="*70)
    print("### " + label)
    if kw.get("binary"):
        print("--- input (bytes) ---"); print(repr(content))
    else:
        print("--- input (numbered) ---")
        for i, ln in enumerate(content.split("\n")):
            print("%3d|%s" % (i, ln))
    print("--- exit=%d ---" % res["exit"])
    if res["stderr"].strip():
        print("STDERR: " + repr(res["stderr"]))
    if "cards" in res:
        if not res["cards"]:
            print("(no cards)")
        for c in res["cards"]:
            k = list(c["content"].keys())[0]
            body = c["content"][k]
            if k == "basic":
                print("  [%d,%d] BASIC q=%s a=%s" % (c["line"][0], c["line"][1], repr(body["question"]), repr(body["answer"])))
            else:
                print("  [%d,%d] CLOZE t=%s span=(%d,%d)" % (c["line"][0], c["line"][1], repr(body["text"]), body["start"], body["end"]))
    if "stdout" in res: print("STDOUT: " + res["stdout"])
    if "parse_err" in res: print("PARSE_ERR " + res["parse_err"])
    return res
PYEOF
